-- Product metadata and exact originals accompany bounded Base import streams.
-- Existing jobs, source claims, plans and applied migrations are unchanged.
CREATE TABLE feedback_import_bundles (
 id TEXT PRIMARY KEY NOT NULL REFERENCES ik_jobs(id),
 fingerprint TEXT NOT NULL,
 receipt_json TEXT NOT NULL,
 originals_json TEXT NOT NULL,
 sealed INTEGER NOT NULL DEFAULT 0 CHECK(sealed IN(0,1))
);
CREATE TABLE feedback_import_original_chunks (
 bundle_id TEXT NOT NULL REFERENCES feedback_import_bundles(id) ON DELETE CASCADE,
 artifact INTEGER NOT NULL,
 ordinal INTEGER NOT NULL,
 bytes TEXT NOT NULL,
 PRIMARY KEY(bundle_id,artifact,ordinal)
);
CREATE TRIGGER feedback_bundle_maintenance BEFORE INSERT ON feedback_import_bundles
 WHEN (SELECT phase FROM data_state WHERE singleton=1) NOT IN ('idle','applying')
 BEGIN SELECT RAISE(ABORT,'data_busy'); END;
CREATE TRIGGER feedback_original_maintenance BEFORE INSERT ON feedback_import_original_chunks
 WHEN (SELECT phase FROM data_state WHERE singleton=1) NOT IN ('idle','applying')
 BEGIN SELECT RAISE(ABORT,'data_busy'); END;

CREATE TABLE feedback_import_native_revision(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL);
INSERT INTO feedback_import_native_revision VALUES(1,0);
CREATE TABLE feedback_import_reversals(job_id TEXT PRIMARY KEY,revision INTEGER NOT NULL);
