CREATE TRIGGER feedback_native_roadmap_update_versions_update AFTER UPDATE ON "roadmap_update_versions" BEGIN UPDATE feedback_import_native_revision SET revision=revision+1 WHERE singleton=1; END;
CREATE TRIGGER feedback_native_roadmap_update_versions_delete AFTER DELETE ON "roadmap_update_versions" BEGIN UPDATE feedback_import_native_revision SET revision=revision+1 WHERE singleton=1; END;
CREATE TRIGGER feedback_native_tags_insert AFTER INSERT ON "tags" BEGIN UPDATE feedback_import_native_revision SET revision=revision+1 WHERE singleton=1; END;
CREATE TRIGGER feedback_native_tags_update AFTER UPDATE ON "tags" BEGIN UPDATE feedback_import_native_revision SET revision=revision+1 WHERE singleton=1; END;
CREATE TRIGGER feedback_native_tags_delete AFTER DELETE ON "tags" BEGIN UPDATE feedback_import_native_revision SET revision=revision+1 WHERE singleton=1; END;
CREATE TABLE feedback_import_receipt_notes(job_id TEXT PRIMARY KEY REFERENCES ik_jobs(id),kind TEXT NOT NULL,source_id TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TRIGGER feedback_bundle_immutable BEFORE UPDATE ON feedback_import_bundles WHEN OLD.sealed=1 AND (SELECT phase FROM data_state WHERE singleton=1)!='applying' BEGIN SELECT RAISE(ABORT,'feedback_bundle_changed'); END;
CREATE TRIGGER feedback_original_immutable_update BEFORE UPDATE ON feedback_import_original_chunks WHEN (SELECT phase FROM data_state WHERE singleton=1)!='applying' BEGIN SELECT RAISE(ABORT,'feedback_original_changed'); END;
CREATE TRIGGER feedback_original_immutable_delete BEFORE DELETE ON feedback_import_original_chunks WHEN (SELECT phase FROM data_state WHERE singleton=1)!='applying' BEGIN SELECT RAISE(ABORT,'feedback_original_changed'); END;
CREATE TRIGGER feedback_original_sealed_insert BEFORE INSERT ON feedback_import_original_chunks WHEN (SELECT sealed FROM feedback_import_bundles WHERE id=NEW.bundle_id)=1 AND (SELECT phase FROM data_state WHERE singleton=1)!='applying' AND NOT EXISTS(SELECT 1 FROM feedback_import_original_chunks WHERE bundle_id=NEW.bundle_id AND artifact=NEW.artifact AND ordinal=NEW.ordinal AND bytes=NEW.bytes) BEGIN SELECT RAISE(ABORT,'feedback_original_changed'); END;
